const meta = await fetch('./assets/atlas.json').then(r=>r.json());
const sprites = await Promise.all(['props-atlas.png','ticket-counter.png'].map(async file=>{const image = new Image();image.src='./assets/'+file;await image.decode();return [file,image]}));
const images=Object.fromEntries(sprites), assets=meta.assets;
const descriptions={seat:['帶杯架嘅酒紅影院座椅。可重複排列成影廳座位。','影廳座位'],ticket_kiosk:['自助購票設備，與有人手服務嘅售票櫃枱分開。','自助購票'],concession_counter:['木色檯面、酒紅飾面，供小食服務與食品展示。','小食服務'],popcorn_machine:['獨立爆谷機，可配合小食櫃位組合放置。','食品設備'],soda_dispenser:['三款飲品按鈕、接杯區與滴水盤。','飲品設備'],recycling_bins:['垃圾與回收分開，供大堂及散場動線使用。','清潔設施'],cleaning_cart:['包含地拖、清潔用品、桶與車輪。','清潔設備'],plant:['米白花盆，配合休息區、大堂及出入口。','裝飾'],ticket_counter:['有人手服務嘅售票櫃枱，設收銀機、出票口及客人顯示屏。','職員售票']};
let selected=assets.find(a=>a.id==='ticket_counter'), view='scene', grid=true, dark=false, zoom=1;
const stage=document.querySelector('#stage'), ctx=stage.getContext('2d');
function drawSprite(c,a,x,y,width){const [sx,sy,sw,sh]=a.region;const h=width*sh/sw;c.imageSmoothingEnabled=false;c.drawImage(images[a.file],sx,sy,sw,sh,Math.round(x-width/2),Math.round(y-h),Math.round(width),Math.round(h));}
function fitSprite(canvas,a,factor=1){const c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);drawSprite(c,a,canvas.width/2,canvas.height*.88,Math.min(canvas.width*.74,canvas.height*.72*a.region[2]/a.region[3])*factor)}
function select(a){selected=a;document.querySelector('#asset-name').textContent=a.name;document.querySelector('#asset-description').textContent=descriptions[a.id][0];document.querySelector('#asset-use').textContent=descriptions[a.id][1];document.querySelector('#asset-footprint').textContent=a.footprint.join(' × ')+' 格';document.querySelector('#asset-size').textContent=a.region.slice(2).join(' × ')+' px';document.querySelector('#resource-link').href=`assets/props/${a.id}.tres`;document.querySelector('#caption').textContent=descriptions[a.id][0];for(const el of document.querySelectorAll('[data-asset]')){el.classList.toggle('active',el.dataset.asset===a.id);el.setAttribute('aria-pressed',String(el.dataset.asset===a.id))}fitSprite(document.querySelector('#selected'),a,zoom);draw();}
for(const [i,a] of assets.entries()){const b=document.createElement('button');b.className='asset-button';b.dataset.asset=a.id;b.innerHTML=`<span class="asset-num">${String(i+1).padStart(2,'0')}</span><span>${a.name}</span>`;b.onclick=()=>select(a);document.querySelector('#asset-buttons').append(b);const thumb=document.createElement('button');thumb.className='thumb';thumb.dataset.asset=a.id;thumb.innerHTML=`<small>${String(i+1).padStart(2,'0')}</small><canvas width="220" height="180" aria-hidden="true"></canvas><span>${a.name}</span>`;thumb.onclick=()=>select(a);document.querySelector('#asset-strip').append(thumb);fitSprite(thumb.querySelector('canvas'),a)}
const p=(x,y)=>[500+(x-y)*28,110+(x+y)*14];
function polygon(points,fill,stroke){ctx.beginPath();for(const[i,q]of points.entries())i?ctx.lineTo(...q):ctx.moveTo(...q);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.6;ctx.stroke()}}
function floor(x,y,fill){const[a,b]=p(x,y);polygon([[a,b],[a+28,b+14],[a,b+28],[a-28,b+14]],fill,grid?'#c3b4a077':null)}
function wall(x1,y1,x2,y2,h,color){const[a,b]=p(x1,y1),[c,d]=p(x2,y2);polygon([[a,b],[c,d],[c,d-h],[a,b-h]],color);polygon([[a,b-h],[c,d-h],[c+5,d-h-4],[a+5,b-h-4]],'#6b606b')}
const places=[];for(let y=1;y<5;y++)for(const x of[2,3,4,5,9,10,11,12])places.push(['seat',x,y]);places.push(['plant',1,6],['concession_counter',5,6],['ticket_counter',11,6],['ticket_kiosk',13,7],['ticket_kiosk',14,7],['recycling_bins',1,9],['soda_dispenser',4,9],['popcorn_machine',5,9],['cleaning_cart',9,9],['plant',15,10]);
function drawScene(){for(let y=0;y<12;y++)for(let x=0;x<17;x++)floor(x,y,y<5?(x<7?'#483547':x<8?'#4d4752':'#393646'):((x+y)%2?'#d8cbbb':'#d2c4b1'));wall(0,0,17,0,60,'#48414f');wall(0,0,0,12,60,'#59505a');wall(7,0,7,5,53,'#3b3543');for(const[x,y,w]of[[1,0,5],[9,0,6]]){const[a,b]=p(x,y),[c,d]=p(x+w,y);polygon([[a+3,b-49],[c-3,d-49],[c-3,d-19],[a+3,b-19]],'#e4d3ac');polygon([[a+6,b-45],[c-6,d-45],[c-6,d-22],[a+6,b-22]],'#b8b4c3')}ctx.font='600 12px sans-serif';ctx.fillStyle='#a78e6d';const[a,b]=p(4,11);ctx.fillText('LOBBY / 大堂',a-32,b+22);for(const[id,x,y]of [...places].sort((a,b)=>(a[1]+a[2])-(b[1]+b[2]))){const asset=assets.find(a=>a.id===id),[px,py]=p(x,y);if(id===selected.id){polygon([[px,py-10],[px+20,py],[px,py+10],[px-20,py]],'#c9965055','#bd8d51')}drawSprite(ctx,asset,px,py,asset.world_width*1.03)}}
function drawAtlas(){ctx.font='13px sans-serif';for(const[i,a]of assets.entries()){const col=i%3,row=Math.floor(i/3),x=200+col*350,y=80+row*215;if(a.id===selected.id){ctx.fillStyle=dark?'#5c4048':'#edddd6';ctx.fillRect(x-135,y-12,270,205)}drawSprite(ctx,a,x,y+150,Math.min(190,145*a.region[2]/a.region[3]));ctx.fillStyle=dark?'#e6d9ca':'#7c6058';ctx.textAlign='center';ctx.fillText(a.name,x,y+181)}ctx.textAlign='start'}
function draw(){ctx.clearRect(0,0,stage.width,stage.height);view==='scene'?drawScene():drawAtlas()}
for(const button of document.querySelectorAll('[data-view]'))button.onclick=()=>{view=button.dataset.view;for(const b of document.querySelectorAll('[data-view]'))b.classList.toggle('active',b===button);draw()};document.querySelector('#show-grid').onchange=e=>{grid=e.target.checked;draw()};document.querySelector('#bg-toggle').onclick=e=>{dark=!dark;document.querySelector('#canvas-wrap').classList.toggle('dark',dark);e.currentTarget.textContent=dark?'◩ 淺色背景':'◩ 深色背景';e.currentTarget.setAttribute('aria-pressed',String(dark));draw()};document.querySelector('#zoom').oninput=e=>{zoom=Number(e.target.value);document.querySelector('#zoom-value').textContent=zoom+'×';fitSprite(document.querySelector('#selected'),selected,zoom)};
select(selected);
